AssistantMessageToolRequest(name='create', tool_call_id='tooluse_jwlIE6PAMrnyJ5Z4dvG05m', arguments={'file_text': 'document.addEventListener('DOMContentLoaded', () => {
  const form = document.querySelector('form');
  const radios = document.querySelectorAll('input[type="radio"]');

  // Handle form submission
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    // Get the selected value
    const selectedRadio = document.querySelector('input[name="notification-preference"]:checked');

    if (selectedRadio) {
      const preference = selectedRadio.value;
      console.log('Selected preference:', preference);

      // Show a brief success message
      const originalText = form.querySelector('button[type="submit"]').textContent;
      form.querySelector('button[type="submit"]').textContent = 'Saved! ✓';

      // Reset button text after 2 seconds
      setTimeout(() => {
        form.querySelector('button[type="submit"]').textContent = originalText;
      }, 2000);
    }
  });

  // Keyboard navigation: Ensure arrow keys work within the radio group
  // Note: Native HTML radios handle this automatically, but we ensure proper behavior
  radios.forEach((radio) => {
    radio.addEventListener('keydown', (e) => {
      if (e.key === 'ArrowDown' || e.key === 'ArrowRight') {
        e.preventDefault();
        const nextRadio = Array.from(radios)[(Array.from(radios).indexOf(radio) + 1) % radios.length];
        nextRadio.focus();
        nextRadio.checked = true;
      } else if (e.key === 'ArrowUp' || e.key === 'ArrowLeft') {
        e.preventDefault();
        const prevRadio = Array.from(radios)[(Array.from(radios).indexOf(radio) - 1 + radios.length) % radios.length];
        prevRadio.focus();
        prevRadio.checked = true;
      }
    });
